import json

def process_sales_data(DATA):
    totals = collections.defaultdict(float)
    valid_rows = 0
    rejected_rows = 0
    by_region = {}

    for row in DATA:
        try:
            amount = float(row['amount'].strip())
            region = row['region']
            totals[region] += amount
            valid_rows += 1
            if region not in by_region or totals[region] > by_region[region]['total']:
                by_region[region] = {'total': totals[region], 'count': 1}
            elif totals[region] == by_region[region]['total'] and region < by_region[region]['region']:
                by_region[region]['count'] += 1
        except ValueError:
            rejected_rows += 1

    top_region = sorted(by_region.items(), key=lambda x: (-x[1]['total'], x[0]))[0][0]

    return json.dumps({
        'total': round(sum(totals.values()), 2),
        'valid_rows': valid_rows,
        'rejected_rows': rejected_rows,
        'by_region': {region: {'total': round(total, 2), 'count': count} for region, (total, count) in by_region.items()},
        'top_region': top_region
    })

print(process_sales_data(DATA))

